statement:
The array `nums` holds three side lengths. They make a triangle only when every side is strictly shorter than the other two sides added together. Return one of these strings:

- `"none"` if the three lengths do not make a triangle;
- `"equilateral"` if all three lengths are the same;
- `"isosceles"` if exactly two of the lengths are the same;
- `"scalene"` if the three lengths are all different.

validator:
function validate([nums]) {
  if (!Array.isArray(nums) || nums.length !== 3) return 'nums holds exactly 3 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each side is an integer from 1 to 100.';
  return null;
}

reference:
function triangleType(nums) {
  const [a, b, c] = [...nums].sort((x, y) => x - y);
  if (a + b <= c) {
    return "none";
  }
  if (a === c) {
    return "equilateral";
  }
  if (a === b || b === c) {
    return "isosceles";
  }
  return "scalene";
}

brute:
function triangleType(nums) {
  for (let i = 0; i < 3; i++) {
    const others = nums.filter((_, index) => index !== i);
    if (others[0] + others[1] <= nums[i]) return "none";
  }
  const distinct = new Set(nums).size;
  return distinct === 1 ? "equilateral" : distinct === 2 ? "isosceles" : "scalene";
}

